// /pipeline and /pipeline.json: how items move through the catalogue, read from PIPELINE (generated by tools/pipeline.mjs from the ledgers the loops write).
// Every number on the page is a field of that object; the sentences state the rules the code applies (ps/pipeline.js RULES).
import * as ui from './kit/index.js';
import { esc } from './catalog.js';
import { PIPELINE } from './pipeline.gen.js';

const n = v => v == null ? 'not measured' : Number(v).toLocaleString('en-US');
const when = iso => String(iso || '').slice(0, 16).replace('T', ' ') + ' UTC';
const STATUS = { ok: 'Moving', stalled: 'Stalled', warming: 'Not enough history to judge yet' };

export function pipelineData(p = PIPELINE) {
  return { as_of: p.at, health: p.health, rules: p.rules, stages: p.stages.map(s => ({ id: s.id, label: s.label, what: s.what, count: p.counts[s.count] ?? null, producer: s.producer, consumer: s.consumer })), counts: p.counts, advocate_queue: p.queue, recent_movements: p.log, history: p.history };
}

export function pipelineBody(p = PIPELINE) {
  const h = p.health, c = p.counts, r = p.rules;
  const stats = ui.stats([
    { value: STATUS[h.status] || h.status, label: `pipeline status over the last ${h.covered_days} days` },
    { value: n(h.substantive_moves), label: `substantive moves in the window (the floor is ${r.min_substantive_7d})` },
    { value: n(h.intake_moves), label: 'new problems read in (inflow, never counted as progress)' },
    { value: h.days_since_substantive == null ? 'none yet' : h.days_since_substantive + ' days', label: 'since the last substantive move' },
  ]);
  const stages = ui.table({ caption: 'Where items are, by stage', head: ['Stage', 'Items', 'What it counts', 'Written by', 'Read by'], rows: p.stages.map(s => [esc(s.label), n(c[s.count]), esc(s.what), esc(s.producer), esc(s.consumer)]) });
  const by = Object.entries(h.by_kind || {}).map(([k, v]) => `<li>${esc(k.replace(/_/g, ' '))}: +${v}</li>`).join('');
  const q = p.queue.length ? ui.table({ caption: 'Problems with an advocate now', head: ['Rank', 'Problem', 'Graph suggests', 'Evidence found', 'Turns', 'Last move'], rows: p.queue.map(x => [x.rank, esc(x.title), esc((x.candidates || []).join(', ') || 'nothing yet'), n(x.hits), x.turns, when(x.last_move)]) }) : '<p>No problem is queued.</p>';
  const log = p.log.length ? `<ul>${[...p.log].reverse().slice(0, 15).map(x => `<li>${when(x.at)}: ${esc(x.id)}: ${esc(x.event)}</li>`).join('')}</ul>` : '<p>No movement recorded yet.</p>';
  return `${ui.breadcrumbs([{ label: 'Home', href: '/' }, { label: 'Pipeline' }])}<h1>Pipeline</h1>
<p class="lede">How a problem becomes a published, checked, connected solution, and whether anything is actually moving. Updated ${when(p.at)}. <a href="/pipeline.json">JSON</a></p>
${ui.section({ id: 'now', title: 'Is it moving?', body: stats + (h.reasons.length ? `<p><b>${h.status === 'stalled' ? 'Why it is stalled' : 'Note'}:</b> ${esc(h.reasons.join('; '))}.</p>` : '') + `<p>A move is a count that rose in a way a reader can see: a queued problem gained evidence, a solution was added, checked or modelled, a synthesis was proposed or verified, or a graph lead was consumed. ${esc(h.trivial_note)} The probe fails when fewer than ${r.min_substantive_7d} substantive moves happen in ${r.window_days} days or when none happens for ${r.max_days_without_move} days.</p>${by ? `<p>Moves in the window:</p><ul>${by}</ul>` : ''}` })}
${ui.section({ id: 'stages', title: 'Stages', body: stages })}
${ui.section({ id: 'queue', title: 'Advocates', body: `<p>Each problem in the queue has one advocate, a rule in code, not a person: it must produce a move (evidence found, a solution listed, a lead consumed) within ${r.patience_days} days or it steps aside for ${r.cooldown_days} days and the next ranked problem with no solution takes the slot. The queue holds ${r.queue_size} problems.</p>` + q })}
${ui.section({ id: 'recent', title: 'Recent movements in the queue', body: log })}`;
}
